#[test]
fn test_tile_squarify_with_zero_value_children() {
    let children = vec![
        TreemapNode::new("A", 10.0),
        TreemapNode::new("B", 0.0),
        TreemapNode::new("C", 0.0),
    ];

    let rects = tile_squarify(&children, 0.0, 0.0, 100.0, 100.0, 10.0);
    // Should not panic and should return at least the non-zero child's rect
    assert!(!rects.is_empty());
    assert!(rects.iter().all(|(x0, y0, x1, y1)| x0.is_finite()
        && y0.is_finite()
        && x1.is_finite()
        && y1.is_finite()));
}

#[test]
fn test_treemap_responsive_size_defaults_and_fixed_opt_in() {
    let root = TreemapNode::new("Root", 100.0);

    crate::assert_default_chart_size(treemap(&root).chart_size);
    crate::assert_fixed_chart_size(treemap(&root).size(420.0, 260.0).chart_size, 420.0, 260.0);
    crate::assert_fill_chart_size(
        treemap(&root)
            .size(420.0, 260.0)
            .fill()
            .min_size(360.0, 240.0)
            .aspect_ratio(1.5)
            .chart_size,
        360.0,
        240.0,
        Some(1.5),
    );
}
